ALTER TABLE "result_batches" ADD CONSTRAINT "result_batches_review_actors" CHECK (("result_batches"."status" = 'draft' or ("result_batches"."submitted_by_account_id" is not null and "result_batches"."submitted_by_membership_id" is not null)) and ("result_batches"."status" in ('draft','submitted') or ("result_batches"."approved_by_account_id" is not null and "result_batches"."approved_by_membership_id" is not null)) and ("result_batches"."status" not in ('published','superseded','withdrawn') or ("result_batches"."published_at" is not null and "result_batches"."published_by_account_id" is not null and "result_batches"."published_by_membership_id" is not null)));